import collections
import datetime
import hashlib
import json
import pathlib
import sys

INVENTORY = pathlib.Path("/data/users/ali/vla_wam/raw/wmf_ablation_001_20260912/control/jobs/timing-d1-development-sidecar-001/raw/d1_development_request_inventory.json")
ROOT = pathlib.Path("/data/users/ali/vla_wam/raw/wmf_ablation_001_20260912")

def identity(path):
    digest = hashlib.sha256()
    count = 0
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
            count += len(chunk)
    return {"path": str(path), "bytes": count, "sha256": digest.hexdigest()}

def reject_symlinks(path):
    current = path
    while True:
        if current.is_symlink():
            raise RuntimeError("symlink component rejected: " + str(current))
        if current == ROOT:
            return
        parent = current.parent
        if parent == current:
            raise RuntimeError("path is outside expected study root")
        current = parent

def key(value):
    return json.dumps(value, separators=(",", ":"), sort_keys=True)

def counter_json(counter):
    return dict(sorted(counter.items()))

reject_symlinks(INVENTORY)
if not INVENTORY.is_file() or INVENTORY.stat().st_size > 16 * 1024 * 1024:
    raise RuntimeError("D1 sidecar inventory unavailable or oversized")
inventory_identity = identity(INVENTORY)
inventory = json.loads(INVENTORY.read_text(encoding="utf-8"))
unsigned = dict(inventory)
payload_sha256 = unsigned.pop("payload_sha256", None)
calculated_payload_sha256 = hashlib.sha256(json.dumps(unsigned, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False).encode("utf-8")).hexdigest()
if payload_sha256 != calculated_payload_sha256:
    raise RuntimeError("D1 sidecar inventory payload signature changed")
entries = inventory.get("request_receipts")
if inventory.get("schema_version") != "wmf-development-timing-request-inventory-v1" or inventory.get("study_id") != "WMF-ABLATION-001" or inventory.get("model_id") != "D1" or not isinstance(entries, list) or len(entries) != 912:
    raise RuntimeError("D1 sidecar inventory contract changed")
by_index = {str(index): {"count": 0, "rgb_shapes": collections.Counter(), "tensor_shapes": collections.Counter(), "latent_shapes": collections.Counter(), "rank0_start_before": collections.Counter(), "rank0_start_after": collections.Counter(), "rank1_start_before": collections.Counter(), "rank1_start_after": collections.Counter()} for index in range(57)}
by_modulo = {str(index): collections.Counter() for index in range(4)}
cell_counts = collections.Counter()
seen_hashes = set()
measurement_controls = collections.Counter()
official_paths = collections.Counter()
for entry in entries:
    if not isinstance(entry, dict):
        raise RuntimeError("inventory entry is not an object")
    descriptor = entry.get("request_receipt")
    if not isinstance(descriptor, dict):
        raise RuntimeError("request descriptor missing")
    path = pathlib.Path(descriptor.get("path", ""))
    reject_symlinks(path)
    if not path.is_file() or path.stat().st_size > 4 * 1024 * 1024:
        raise RuntimeError("request receipt unavailable or oversized")
    observed = identity(path)
    if observed["sha256"] != descriptor.get("sha256") or observed["bytes"] != descriptor.get("bytes") or observed["sha256"] in seen_hashes:
        raise RuntimeError("request receipt identity mismatch or duplicate")
    seen_hashes.add(observed["sha256"])
    request = json.loads(path.read_text(encoding="utf-8"))
    request_index = entry.get("request_index")
    cell_id = entry.get("cell_id")
    if type(request_index) is not int or not 0 <= request_index < 57 or request.get("request_index") != request_index or not isinstance(cell_id, str):
        raise RuntimeError("request index or cell identity changed")
    decode = request.get("offline_decode")
    rgb = decode.get("decoded_rgb") if isinstance(decode, dict) else None
    tensor = decode.get("decoded_tensor") if isinstance(decode, dict) else None
    latent = request.get("latent_video")
    metrics = request.get("temporal_and_cache_rank_metrics")
    if not isinstance(decode, dict) or decode.get("requested") is not True or decode.get("performed") is not True or not isinstance(rgb, dict) or not isinstance(tensor, dict) or not isinstance(latent, dict) or not isinstance(metrics, list) or len(metrics) != 2 or sorted(row.get("rank") for row in metrics if isinstance(row, dict)) != [0, 1]:
        raise RuntimeError("request decode or rank metrics contract changed")
    ranked = {row["rank"]: row for row in metrics}
    record = by_index[str(request_index)]
    record["count"] += 1
    record["rgb_shapes"][key(rgb.get("shape"))] += 1
    record["tensor_shapes"][key(tensor.get("shape"))] += 1
    record["latent_shapes"][key(latent.get("shape"))] += 1
    for rank in (0, 1):
        before = ranked[rank].get("temporal_before")
        after = ranked[rank].get("temporal_after")
        record[f"rank{rank}_start_before"][key(before.get("current_start_frame") if isinstance(before, dict) else None)] += 1
        record[f"rank{rank}_start_after"][key(after.get("current_start_frame") if isinstance(after, dict) else None)] += 1
    by_modulo[str(request_index % 4)][key(rgb.get("shape"))] += 1
    cell_counts[cell_id] += 1
    measurement_controls[key(request.get("measurement_control"))] += 1
    official_paths[key(request.get("official_action_path"))] += 1
if len(seen_hashes) != 912 or len(cell_counts) != 16 or set(cell_counts.values()) != {57} or any(record["count"] != 16 for record in by_index.values()):
    raise RuntimeError("complete 16-cell by 57-request schedule changed")
serialized_by_index = {}
for request_index, record in by_index.items():
    serialized_by_index[request_index] = {name: (counter_json(value) if isinstance(value, collections.Counter) else value) for name, value in record.items()}
observed_schedule = {request_index: next(iter(record["rgb_shapes"])) if len(record["rgb_shapes"]) == 1 else None for request_index, record in serialized_by_index.items()}
expected_schedule = {str(index): ("[9,352,640,3]" if index % 4 == 0 else "[5,352,640,3]") for index in range(57)}
output = {"schema_version": "wmf-d1-development-cache-schedule-diagnostic-v1", "study_id": "WMF-ABLATION-001", "status": "read_only_summary_complete", "source_attempt": "timing-d1-development-sidecar-001", "inventory": inventory_identity, "inventory_payload_sha256_verified": True, "request_count": len(entries), "unique_request_receipt_hashes": len(seen_hashes), "cell_count": len(cell_counts), "requests_per_cell_distribution": counter_json(collections.Counter(cell_counts.values())), "by_request_index": serialized_by_index, "decoded_rgb_shapes_by_request_index_modulo_four": {index: counter_json(value) for index, value in by_modulo.items()}, "exact_modulo_four_shape_schedule_observed": observed_schedule == expected_schedule, "measurement_control_distribution": counter_json(measurement_controls), "official_action_path_distribution": counter_json(official_paths), "science_counts": {"model_requests": 0, "behavioral_actions": 0, "physical_resets": 0, "robot_episodes": 0, "behavioral_cells": 0}, "scientific_qualification": False, "claim_boundary": "Read-only cache/decode schedule summary of immutable D1 development receipts; not timing qualification, annotation, or forecast accuracy.", "completed_at_utc": datetime.datetime.now(datetime.timezone.utc).isoformat()}
publish = pathlib.Path(sys.argv[1]) / "publish"
publish.mkdir(parents=True, exist_ok=False)
with (publish / "diagnostic.json").open("x", encoding="utf-8") as stream:
    json.dump(output, stream, indent=2, sort_keys=True)
    stream.write("\n")
print(json.dumps({"status": output["status"], "request_count": len(entries), "exact_schedule": output["exact_modulo_four_shape_schedule_observed"]}, sort_keys=True))
